import ida_bytes
for addr in [0x1424b0ea3,0x1424b3a83,0x1424cefe8]:
    raw=ida_bytes.get_bytes(addr,20)
    if raw:
        for i in range(len(raw)):
            if raw[i]==0:
                s=raw[:i].decode(errors='replace')
                print(hex(addr)+': '+repr(s))
                break
        else:
            s=raw.decode(errors='replace')
            print(hex(addr)+': '+repr(s))
